template:
struct Logger {
    buffer: String,
}

impl Logger {
    fn flush(&mut self) -> String {
        ⟦take_fn⟧(⟦take_arg⟧)
    }
}

fn main() {
    let mut log = Logger { buffer: String::from("hello") };
    let msg = log.flush();
    println!("{msg}");
}

tests:
#[test]
fn flushes_buffer() {
    let mut log = Logger { buffer: String::from("hello") };
    let msg = log.flush();
    assert_eq!(msg, "hello");
    assert_eq!(log.buffer, "");
}
